//! Task descriptors, states and the task table.
//!
//! A [`TaskDef`] is a compile-time constant generated by the `#[task]` macro
//! and placed into the `.rtos.tasks` link section. `start()` walks that
//! section to build the runtime task table (`Task` entries with stack
//! pointers and scheduler state).

/// Maximum number of tasks the kernel can hold (including the idle task).
pub const MAX_TASKS: usize = 8;

/// Default task stack size in bytes (used by `#[task]` when `stack` is
/// omitted).
pub const DEFAULT_STACK_SIZE: usize = 1024;

/// Task priority range: 0 (lowest) ..= `MAX_PRIO`.
pub const MAX_PRIO: u8 = 7;

/// A compile-time task descriptor, produced by the `#[task]` macro.
///
/// One of these is emitted into the `.rtos.tasks` link section for every
/// task; `start()` collects them between `__rtos_tasks_start` and
/// `__rtos_tasks_end`.
#[repr(C)]
pub struct TaskDef {
    /// Task entry point (returns `!`).
    pub entry: unsafe extern "C" fn() -> !,
    /// Base pointer of the task's stack.
    pub stack: *mut u8,
    /// Stack size in bytes.
    pub stack_size: usize,
    /// Declared (base) priority.
    pub priority: u8,
    /// Task name for debugging.
    pub name: &'static str,
}

// `TaskDef` is placed in a `static` by the `#[task]` macro; it is only ever
// read by the scheduler, so it is safe to share.
unsafe impl Sync for TaskDef {}

/// Runtime state of a task.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TaskState {
    /// Waiting in the ready queue.
    Ready,
    /// Currently executing.
    Running,
    /// Blocked until a tick deadline.
    BlockedSleep,
    /// Blocked waiting on a semaphore/mutex (with optional deadline).
    BlockedSem,
}

/// Why a blocked task is waiting.
#[derive(Clone, Copy)]
pub enum Wait {
    /// Sleeping until `deadline` (inclusive tick).
    Sleep(u32),
    /// Waiting on a semaphore until `deadline` (0 = forever).
    Sem {
        sem: *const (),
        deadline: u32,
        /// Set when `give` granted us the count.
        granted: bool,
    },
}

/// A runtime task control block.
pub struct Task {
    /// Entry point (for first scheduling).
    pub entry: unsafe extern "C" fn() -> !,
    /// Saved stack pointer (only meaningful when not `Running`).
    pub sp: *mut u32,
    /// Bottom of the task stack (for canary checks).
    pub stack_bottom: *mut u8,
    /// Stack size in bytes.
    pub stack_size: usize,
    /// Declared (base) priority.
    pub base_prio: u8,
    /// Effective priority (raised while inheriting on a mutex).
    pub cur_prio: u8,
    /// Task name.
    pub name: &'static str,
    /// Current scheduler state.
    pub state: TaskState,
    /// Blocking reason (valid while `Blocked*`).
    pub wait: Option<Wait>,
}

// `Task` lives only inside the single-core scheduler, accessed inside
// critical sections; the raw pointers are safe there.
unsafe impl Send for Task {}

/// A read-only snapshot of one task, for debugging and logging.
#[derive(Clone, Copy, Debug)]
pub struct TaskInfo {
    /// Task name.
    pub name: &'static str,
    /// Current scheduler state.
    pub state: TaskState,
    /// Declared (base) priority.
    pub base_prio: u8,
    /// Effective priority (raised while inheriting on a mutex).
    pub cur_prio: u8,
}
